import {assertResearchSourceIdentity} from '../../shared/permittingSourceIdentity.mjs';
import {attachScanReporter} from '../../shared/permittingScanReporter.mjs';
import { createClientFromRequest } from 'npm:@base44/sdk@0.8.23';
import { withEntityRateLimitRetry } from '../../shared/entityRateLimitRetry.ts';
import { normalizePermittingResearchInput } from '../../shared/permittingResearchInput.ts';
import { sanitizeJurisdictionResearch } from '../../shared/jurisdictionResearchSanitizer.ts';
import {officeResearchPrompt,officeResearchResponseSchema,normalizeOfficeResearch} from '../../shared/permittingOfficeResearch.mjs';

Deno.serve(async (req) => {
  try {
    const base44 = withEntityRateLimitRetry(createClientFromRequest(req));
    const user = await base44.auth.me();
    if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 });

    const body = await req.json().catch(() => null);
    let researchInput;
    try {
      researchInput = normalizePermittingResearchInput(body);
    } catch (validationError) {
      return Response.json({ error: validationError?.message || 'Invalid permitting research input' }, { status: 400 });
    }
    const { jurisdictionName, jurisdictionState, jurisdictionType, includeParentCounty } = researchInput;

    // Main research agent prompt - with detailed instructions for accurate data gathering
    const researchPrompt = `You are a specialized research agent for gathering sign permitting information. Your goal is to find ACCURATE, VERIFIED information from official sources.

JURISDICTION TARGET: ${jurisdictionName} ${jurisdictionType}, ${jurisdictionState}

=== CRITICAL RULES ===
1. ONLY use official government sources (city/county/state websites)
2. DO NOT fabricate, guess, or hallucinate URLs or data
3. If information cannot be verified, return null for that field instead of placeholder text
4. Cross-reference information when possible
5. Prioritize official ordinances and zoning codes over secondary sources
6. For each URL you provide, verify it exists and is from an official government domain
7. If regulatory requirements come from a proposed, draft, newly rewritten, or comprehensive replacement zoning/sign code, flag authority_candidate.is_comprehensive_rewrite=true. A posted rewrite is not current law merely because it is publicly available.

=== RESEARCH OBJECTIVES ===

A. OFFICIAL WEBSITES
   - Find the official ${jurisdictionName} government website
   - Find the official permitting/zoning department page
   - Verify these are actual current URLs from official sources

B. SIGN PERMIT REQUIREMENTS
   Research the actual sign permit rules including:
   - Does a permit requirement exist? (yes/no)
   - Maximum sign area in square feet (if regulated)
   - Maximum sign height in feet (if regulated)
   - Setback requirements from property lines/streets
   - Are illuminated signs allowed?
   - Are electronic/digital signs allowed?
   - Permit application fees (fee range if varies)
   - Processing timeline (days to approve)
   - Any material restrictions or design standards

C. REGULATORY DOCUMENTS, FORMS, AND ONLINE PORTALS
   Search the official jurisdiction site deeply enough to identify every sign-permitting resource you can verify, including:
   - Sign ordinance(s) or adopted code pages/PDFs governing signs
   - Zoning code chapters/sections mentioning signs
   - Sign permit application forms, building/zoning permit forms, and supporting checklists
   - Fee schedules or official permit-fee pages/PDFs
   - Design guidelines and submission requirement documents
   - Official online permit/application portals or web forms used to submit sign/zoning/building permits

   DOCUMENT CAPTURE RULES:
   - Do not stop after finding the department landing page. Follow official links to the actual ordinance, form, PDF, portal, or code page.
   - Return each verified resource as a separate documents[] item with a useful title, direct official URL, and doc_type.
   - Use doc_type "permit_application" for downloadable application forms and official online application/permit portals.
   - Use doc_type "zoning_code" for official HTML code sections when no PDF exists.
   - Prefer direct PDF/form/code URLs over generic department homepages when both are available.
   - If an official portal is the only application method, include that portal in documents[] even though it is not a downloadable file.
   - Never invent a form or document URL. If a resource cannot be verified, omit it.

D. CONTACT INFORMATION
   Gather from official sources:
   - Department/office responsible for permits
   - Official phone number
   - Official email address
   - Physical office address

E. PROPERTY LOOKUP DATABASE
   Find the jurisdiction's property/parcel lookup system:
   - Many counties have CAGIS or equivalent systems
   - Usually found on county assessor or property appraiser website
   - Should allow searching by address or parcel number

${includeParentCounty && jurisdictionType !== 'county' ? `F. PARENT COUNTY INFORMATION
   Since this is a ${jurisdictionType}:
   - Research the actual parent county
   - Find parent county permitting resources
   - Identify which rules come from county vs. local jurisdiction
   - Document parent county ordinances that apply` : ''}

${officeResearchPrompt()}
=== RESPONSE FORMAT ===
Return ONLY valid JSON with this structure. Leave fields null if not found:

{
  "website_url": "https://official-url.gov",
  "permitting_url": "https://official-permitting-page.gov",
  "cagis_database_url": "https://property-lookup-system.gov",
  "ai_summary": "2-3 sentence summary of the sign permit process and key requirements",
  "contact_info": {
    "department": "Official Department Name",
    "phone": "Phone number from official source",
    "email": "Email from official source",
    "address": "Physical mailing address from official source"
  },
  "permit_requirements": {
    "requires_permit": true,
    "max_sign_area_sqft": 200,
    "max_height_ft": 25,
    "setback_requirements": "Description from official ordinance",
    "illumination_allowed": true,
    "electronic_signs_allowed": false,
    "fee_range": "$150-$300",
    "processing_time": "10-15 business days"
  },
  "documents": [
    {
      "title": "Sign Ordinance Chapter 25",
      "url": "https://official-source-url.gov/ordinance",
      "doc_type": "sign_ordinance",
      "source": "local",
      "verification_notes": "Found on official city website, last updated 2024"
    }
  ],
  "sqft_width_height_rules": "Detailed rules from official ordinance text",
  "height_allowances": "Specific height regulations by location type",
  "setback_rules": "Setback distance requirements from official code",
  "lighting_allowances": "Illumination and lighting restrictions",
  "authority_candidate": { "is_comprehensive_rewrite": false, "kind": "current_adopted|comprehensive_rewrite|zoning_rewrite|narrow_amendment|unknown", "notes": "Explain the authority classification" },
  ${includeParentCounty && jurisdictionType !== 'county' ? `"parent_county": {
    "name": "Parent County Name",
    "website_url": "https://official-county-url.gov",
    "permitting_url": "https://county-permitting.gov",
    "contact_info": { "department": "", "phone": "", "email": "", "address": "" },
    "documents": [
      { "title": "County Sign Ordinance", "url": "...", "doc_type": "sign_ordinance", "source": "county" }
    ]
  },` : ''}
  "data_quality": {
    "sources_checked": ["list of official sources you checked"],
    "confidence": "high|medium|low",
    "notes": "Any limitations or caveats about the data"
  }
}

=== QUALITY CHECKLIST ===
Before returning:
☐ All URLs are from official government domains
☐ No URLs were fabricated or guessed
☐ Contact info is from official sources
☐ Data comes from current ordinances (not outdated)
☐ Specific numbers/rules can be traced to actual documents
☐ Every verified application form, online submission portal, fee schedule, sign ordinance, and zoning-code resource found is represented in documents[]
☐ documents[] entries use direct official resource URLs, not merely generic department homepages when a deeper verified link exists
☐ null is used when data cannot be verified
☐ Parent county information is accurate if included`;

    if(body?.scan_run_id && user.role==='admin'){
      const row=await base44.asServiceRole.entities.PermittingScanRun.get(body.scan_run_id);
      if(row?.owner_id===user.id && row.target_name===jurisdictionName && row.status==='running')await attachScanReporter(base44.asServiceRole.entities.PermittingScanRun,row.id).emit({kind:'search_instructions',detail:researchPrompt},{stage:'AI research — instructions submitted',indeterminate:true});
    }
    const result = await base44.asServiceRole.integrations.Core.InvokeLLM({
      prompt: researchPrompt,
      add_context_from_internet: true,
      response_json_schema: {
        type: "object",
        properties: {
          website_url: { type: ["string", "null"] },
          permitting_url: { type: ["string", "null"] },
          cagis_database_url: { type: ["string", "null"] },
          ai_summary: { type: ["string", "null"] },
          contact_info: { type: "object" },
          office_research: officeResearchResponseSchema,
          permit_requirements: { type: "object" },
          documents: {
            type: "array",
            items: {
              type: "object",
              properties: {
                title: { type: "string" },
                url: { type: "string" },
                doc_type: {
                  type: "string",
                  enum: ["sign_ordinance", "permit_application", "zoning_code", "fee_schedule", "checklist", "other"]
                },
                source: { type: "string" },
                verification_notes: { type: "string" }
              },
              required: ["title", "url", "doc_type"]
            }
          },
          parent_county: { type: ["object", "null"] },
          sqft_width_height_rules: { type: ["string", "null"] },
          height_allowances: { type: ["string", "null"] },
          setback_rules: { type: ["string", "null"] },
          lighting_allowances: { type: ["string", "null"] },
          authority_candidate: { type: "object" },
          data_quality: { type: "object" }
        }
      }
    });

    const data = sanitizeJurisdictionResearch(typeof result === 'string' ? JSON.parse(result) : result);
    assertResearchSourceIdentity({name:jurisdictionName,state:jurisdictionState},data);
    data.office_research = normalizeOfficeResearch(data.office_research,{jurisdiction:{name:jurisdictionName,state:jurisdictionState,type:jurisdictionType}});

    return Response.json({ 
      success: true, 
      data,
      ...(body?.scan_run_id?{research_instructions:researchPrompt}:{}),
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    console.error('jurisdictionResearchAgent error:', error?.message || error);
    if (error?.code === 'SOURCE_IDENTITY_REVIEW_REQUIRED') return Response.json({error:error.message,code:error.code},{status:409});
    return Response.json({ error: 'Jurisdiction research could not be completed safely' }, { status: 500 });
  }
});

import { createClientFromRequest } from 'npm:@base44/sdk@0.8.23';
import { withEntityRateLimitRetry } from '../../shared/entityRateLimitRetry.ts';
import { ensureConvergentRegulationAlertCreate } from '../../shared/regulationAlertPersistence.mjs';
import { loadAllEntityRows } from '../../shared/pagedEntityRows.ts';
import { hasWorkflowInvocationCapability } from '../../shared/workflowInvocationCapability.ts';

Deno.serve(async (req) => {
  try {
    const base44 = withEntityRateLimitRetry(createClientFromRequest(req));
    const body = await req.json().catch(() => ({}));
    const isScheduledRun = await hasWorkflowInvocationCapability(body, 'auditJurisdictionAccuracy');

    if (!isScheduledRun) {
      const user = await base44.auth.me().catch(() => null);
      if (!user) {
        return Response.json({ error: 'Authentication required' }, { status: 401 });
      }
      if (user.role !== 'admin') {
        return Response.json({ error: 'Admin access required' }, { status: 403 });
      }
    }

    const { jurisdictionId, batchSize = 1, auditOptions = {} } = body;

    const options = {
      checkUrls: true,
      checkRequirements: true,
      checkContact: true,
      ...auditOptions
    };

    // Load jurisdictions
    let jurisdictions;
    if (jurisdictionId) {
      const j = await base44.asServiceRole.entities.JurisdictionProfile.get(jurisdictionId);
      jurisdictions = j ? [j] : [];
    } else {
      const all = await loadAllEntityRows({
        entity: base44.asServiceRole.entities.JurisdictionProfile,
        sort: 'created_date',
        label: 'Jurisdiction accuracy audit catalog',
      });
      jurisdictions = Array.isArray(all) ? all.slice(0, batchSize) : [];
    }

    if (!jurisdictions.length) {
      return Response.json({ success: true, flagged: 0, audited: 0, message: 'No jurisdictions to audit' });
    }

    let totalFlagged = 0;
    const RUN_START = Date.now();
    const MAX_RUN_MS = 50_000; // 50s budget, leave buffer before 60s timeout
    let auditedCount = 0;

    for (const jurisdiction of jurisdictions) {
      if (Date.now() - RUN_START > MAX_RUN_MS) {
        console.warn('Time budget exhausted, remaining jurisdictions will be audited next run');
        break;
      }
      try {
        const issuesFound = await Promise.race([
          auditSingleJurisdiction(base44, jurisdiction, options),
          new Promise((_, reject) => setTimeout(() => reject(new Error('Single jurisdiction audit timed out')), 45_000))
        ]);
        totalFlagged += issuesFound;
      } catch (e) {
        console.error(`Skipping ${jurisdiction.name} due to timeout/error:`, e.message);
      }
      auditedCount++;
    }

    return Response.json({
      success: true,
      audited: auditedCount,
      flagged: totalFlagged
    });

  } catch (error) {
    console.error('auditJurisdictionAccuracy error:', error?.message || error);
    return Response.json({ error: 'Jurisdiction accuracy audit could not be completed safely' }, { status: 500 });
  }
});

async function auditSingleJurisdiction(base44, jurisdiction, options) {
  let issuesCreated = 0;

  try {
    const currentData = {
      website_url: jurisdiction.website_url,
      permitting_url: jurisdiction.permitting_url,
      permit_requirements: jurisdiction.permit_requirements,
      contact_info: jurisdiction.contact_info,
      ai_summary: jurisdiction.ai_summary,
      last_updated: jurisdiction.last_updated
    };

    const checkSections = [];
    if (options.checkUrls) checkSections.push('1. Are the website_url and permitting_url still valid and pointing to the correct government pages?');
    if (options.checkRequirements) checkSections.push('2. Do the permit requirements (max height, area, fees, processing time) match current official information from government websites?');
    if (options.checkContact) checkSections.push('3. Is the contact information (department, phone, email) still accurate?');

    // Fetch fresh data from the research agent, then compare against stored data
    const agentResult = await base44.asServiceRole.functions.invoke('jurisdictionResearchAgent', {
      jurisdictionName: jurisdiction.name,
      jurisdictionState: jurisdiction.state,
      jurisdictionType: jurisdiction.type,
      includeParentCounty: false
    });
    const freshData = agentResult?.data?.data || agentResult?.data || agentResult;

    // Use the accuracy audit agent to compare stored vs fresh data
    const auditConversation = await base44.asServiceRole.agents.createConversation({
      agent_name: 'jurisdiction_accuracy_audit'
    });

    const auditResponse = await base44.asServiceRole.agents.addMessage(auditConversation, {
      role: 'user',
      content: `Audit this jurisdiction.\n\nJurisdiction: ${jurisdiction.name}, ${jurisdiction.state} (${jurisdiction.type})\n\nSTORED data:\n${JSON.stringify(currentData, null, 2)}\n\nFRESH data (just researched from official sources):\n${JSON.stringify(freshData, null, 2)}\n\nChecks to perform:\n${checkSections.join('\n')}\n\nReturn findings as a JSON object with an 'issues_found' array.`
    });

    const lastMessage = auditResponse?.messages?.filter(m => m.role === 'assistant').pop();
    let issues = [];
    try {
      const parsed = typeof lastMessage?.content === 'string' ? JSON.parse(lastMessage.content) : lastMessage?.content;
      issues = parsed?.issues_found || [];
    } catch (e) {
      console.warn('Could not parse audit agent response:', e.message);
    }

    const thirtyDaysAgo = new Date();
    thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

    for (const issue of issues) {
      // Preserve the existing 30-day unread suppression rule, but converge
      // simultaneous audit runs to one canonical alert instead of racing create().
      const alertData = {
        jurisdiction_id: jurisdiction.id,
        jurisdiction_name: jurisdiction.name,
        jurisdiction_state: jurisdiction.state,
        alert_type: ['requirement_change', 'url_change', 'contact_change', 'document_update'].includes(issue.alert_type)
          ? issue.alert_type
          : 'other',
        title: `[Accuracy Audit] ${issue.title}`,
        description: issue.description || '',
        field_changed: issue.field_changed || '',
        previous_value: issue.previous_value || '',
        new_value: issue.new_value || '',
        impact_summary: issue.impact_summary || '',
        severity: ['low', 'medium', 'high', 'critical'].includes(issue.severity) ? issue.severity : 'medium',
        detected_at: new Date().toISOString(),
        is_read: false,
        notification_sent: false
      };

      const alertResult = await ensureConvergentRegulationAlertCreate({
        entity: base44.asServiceRole.entities.RegulationAlert,
        data: alertData,
        identityFields: ['jurisdiction_id', 'field_changed'],
        label: `Accuracy audit alert ${jurisdiction.name || jurisdiction.id} ${issue.field_changed || issue.title || 'issue'}`,
        readMatches: async () => {
          const existingAlerts = await base44.asServiceRole.entities.RegulationAlert.filter({
            jurisdiction_id: jurisdiction.id,
            is_read: false
          });
          return (existingAlerts || []).filter(a =>
            a.field_changed === issue.field_changed &&
            a.title?.includes('[Accuracy Audit]') &&
            new Date(a.detected_at) > thirtyDaysAgo
          );
        },
      });

      if (alertResult.status === 'created') issuesCreated++;
    }
  } catch (e) {
    console.error(`Audit error for ${jurisdiction.name}:`, e.message);
  }

  return issuesCreated;
}

import { createClientFromRequest } from 'npm:@base44/sdk@0.8.23';
import { withEntityRateLimitRetry } from '../../shared/entityRateLimitRetry.ts';
import { jurisdictionProtectionGuards, replaceJurisdictionFieldsIfUnchanged } from '../../shared/jurisdictionPersistence.mjs';
import { invalidateVerifiedJurisdictionAfterResearch } from '../../shared/jurisdictionVerification.ts';
import { mergeJurisdictionResearchDocuments } from '../../shared/jurisdictionResearchDocumentMerge.mjs';
import { gateResearchRegulatoryPromotion } from '../../shared/jurisdictionResearchAuthorityGate.mjs';

Deno.serve(async (req) => {
  try {
    const base44 = withEntityRateLimitRetry(createClientFromRequest(req));
    const user = await base44.auth.me();

    if (user?.role !== 'admin') {
      return Response.json({ error: 'Admin access required' }, { status: 403 });
    }

    const { jurisdictionIds, settings } = await req.json();

    if (!jurisdictionIds || !Array.isArray(jurisdictionIds) || jurisdictionIds.length === 0) {
      return Response.json({ error: 'No jurisdictions selected' }, { status: 400 });
    }

    let updated = 0;
    let skipped = 0;
    let processed = 0;

    for (const jurisdictionId of jurisdictionIds) {
     processed++;
     try {
       const jurisdiction = await base44.entities.JurisdictionProfile.get(jurisdictionId);
       console.log(`[RESEARCH_PROGRESS] Processing ${processed}/${jurisdictionIds.length}: ${jurisdiction?.name}`);

        if (!jurisdiction) continue;

        // Use the jurisdiction research agent for all searches
        const agentResult = await base44.asServiceRole.functions.invoke('jurisdictionResearchAgent', {
          jurisdictionName: jurisdiction.name,
          jurisdictionState: jurisdiction.state,
          jurisdictionType: jurisdiction.type,
          includeParentCounty: jurisdiction.type !== 'county'
        });

        const data = agentResult?.data?.data || agentResult?.data || agentResult;

        // Build update object, respecting manual data protection
        const updateData = {};

        if (settings.updateWebsites && (!settings.skipManualData || !jurisdiction._manual_website_url)) {
          updateData.website_url = data.website_url || jurisdiction.website_url;
        }

        if (settings.updatePermittingUrls && (!settings.skipManualData || !jurisdiction._manual_permitting_url)) {
          updateData.permitting_url = data.permitting_url || jurisdiction.permitting_url;
        }

        if (settings.updateRequirements && (!settings.skipManualData || !jurisdiction._manual_requirements)) {
          updateData.permit_requirements = data.permit_requirements || jurisdiction.permit_requirements;
          updateData.sqft_width_height_rules = data.sqft_width_height_rules || jurisdiction.sqft_width_height_rules;
          updateData.height_allowances = data.height_allowances || jurisdiction.height_allowances;
          updateData.setback_rules = data.setback_rules || jurisdiction.setback_rules;
          updateData.lighting_allowances = data.lighting_allowances || jurisdiction.lighting_allowances;
        }

        if (settings.updateDocuments && (!settings.skipManualData || !jurisdiction._manual_documents)) {
          const newDocs = (data.documents || []).map((d, i) => ({
            id: `ai_${Date.now()}_${i}`,
            title: d.title || "Untitled",
            url: d.url || "",
            doc_type: d.doc_type || "other",
            source: "ai_discovered"
          }));

          const countyDocs = (data.parent_county?.documents || []).map((d, i) => ({
            id: `ai_county_${Date.now()}_${i}`,
            title: `[${data.parent_county.name}] ${d.title || "Untitled"}`,
            url: d.url || "",
            doc_type: d.doc_type || "other",
            source: "ai_discovered"
          }));

          updateData.documents = mergeJurisdictionResearchDocuments(jurisdiction.documents, [...newDocs, ...countyDocs]);
        }

        if (settings.updateRequirements && (!settings.skipManualData || !jurisdiction._manual_requirements)) {
          updateData.contact_info = data.contact_info || jurisdiction.contact_info;
          updateData.ai_summary = data.ai_summary || jurisdiction.ai_summary;
        }
        updateData.parent_county = data.parent_county || jurisdiction.parent_county;
        updateData.last_updated = new Date().toISOString();
        const authorityGatedUpdate = gateResearchRegulatoryPromotion({
          jurisdiction,
          researchData: data,
          updateData,
          documentEvidence: updateData.documents || [],
        }).updateData;
        const finalUpdateData = invalidateVerifiedJurisdictionAfterResearch(jurisdiction, authorityGatedUpdate);

        await replaceJurisdictionFieldsIfUnchanged({
          entity: base44.entities.JurisdictionProfile,
          jurisdiction,
          nextFields: finalUpdateData,
          guardFields: jurisdictionProtectionGuards(jurisdiction, finalUpdateData, {
            respectManualProtection: settings.skipManualData !== false,
          }),
          label: `Jurisdiction batch research ${jurisdiction.name || jurisdictionId}`,
        });
        updated++;
      } catch (e) {
        console.error(`Error updating jurisdiction ${jurisdictionId}:`, e);
        skipped++;
      }
    }

    return Response.json({
      success: true,
      updated,
      skipped,
      total: jurisdictionIds.length
    });
  } catch (error) {
    console.error('batchUpdateJurisdictions error:', error?.message || error);
    return Response.json({ error: 'Jurisdiction batch update could not be completed safely' }, { status: 500 });
  }
});

import { createClientFromRequest } from 'npm:@base44/sdk@0.8.23';
import { withEntityRateLimitRetry } from '../../shared/entityRateLimitRetry.ts';
import { jurisdictionProtectionGuards, replaceJurisdictionFieldsIfUnchanged } from '../../shared/jurisdictionPersistence.mjs';
import { claimRegulationAlertNotification, ensureConvergentRegulationAlertCreate } from '../../shared/regulationAlertPersistence.mjs';
import { loadAllEntityRows } from '../../shared/pagedEntityRows.ts';
import { hasWorkflowInvocationCapability } from '../../shared/workflowInvocationCapability.ts';
